-- =====================================================================
-- GLAMOUR — Supabase schema + seed data
-- Safe to run any number of times:
--   - If `stories` doesn't exist yet, or already matches this schema,
--     nothing destructive happens (existing rows are kept as-is).
--   - If `stories` exists with a different/older schema, it's renamed
--     to a timestamped backup table instead of being touched.
-- Run in your Supabase project's SQL Editor (New query -> paste -> Run)
-- =====================================================================

do $$
declare
  backup_name text;
begin
  if exists (select 1 from information_schema.tables where table_name = 'stories' and table_schema = 'public')
     and not exists (select 1 from information_schema.columns where table_name = 'stories' and table_schema = 'public' and column_name = 'category_slug')
  then
    backup_name := 'stories_old_backup_' || to_char(now(), 'YYYYMMDD_HH24MISS');
    execute format('alter table stories rename to %I', backup_name);
  end if;
end $$;

create table if not exists stories (
  id text primary key,
  category text not null,
  category_slug text not null,
  title text not null,
  excerpt text default '',
  author text default '',
  author_bio text default '',
  author_image text default '',
  image text default '',
  image_caption text default '',
  story_date date default current_date,
  tags text[] default '{}',
  featured boolean default false,
  homepage_latest boolean default false,
  pull_quote text default '',
  body text[] default '{}',
  created_at timestamptz default now()
);

-- Admin allow-list. Anyone can create an account (self-signup via
-- login.html), but only user_ids listed here can add/edit/delete
-- stories. Add your own row here manually after you sign up:
--   Table Editor -> admins -> Insert row -> paste your user's UUID
--   (find it under Authentication -> Users)
create table if not exists admins (
  user_id uuid primary key references auth.users(id) on delete cascade,
  created_at timestamptz default now()
);

-- ---------- Row Level Security ----------

alter table stories enable row level security;

drop policy if exists "Public read access" on stories;
create policy "Public read access" on stories
  for select to anon, authenticated using (true);

drop policy if exists "Authenticated insert" on stories;
drop policy if exists "Admins can insert" on stories;
create policy "Admins can insert" on stories
  for insert to authenticated
  with check (exists (select 1 from admins where user_id = auth.uid()));

drop policy if exists "Authenticated update" on stories;
drop policy if exists "Admins can update" on stories;
create policy "Admins can update" on stories
  for update to authenticated
  using (exists (select 1 from admins where user_id = auth.uid()))
  with check (exists (select 1 from admins where user_id = auth.uid()));

drop policy if exists "Authenticated delete" on stories;
drop policy if exists "Admins can delete" on stories;
create policy "Admins can delete" on stories
  for delete to authenticated
  using (exists (select 1 from admins where user_id = auth.uid()));

alter table admins enable row level security;

drop policy if exists "Users can check their own admin status" on admins;
create policy "Users can check their own admin status" on admins
  for select to authenticated using (user_id = auth.uid());

-- No insert/update/delete policies on admins on purpose: the only way
-- to grant admin access is for you, the project owner, to add a row
-- via the Supabase dashboard. No one can promote themselves.


-- Seed data: your 50 existing stories, carried over as-is
insert into stories
  (id, category, category_slug, title, excerpt, author, author_bio, author_image,
   image, image_caption, story_date, tags, featured, homepage_latest, pull_quote, body)
values
  ('the-modern-ceo-how-top-executives-balance-empires-and-wellne', 'CEO Lifestyle', 'ceo-lifestyle', 'The Modern CEO: How Top Executives Balance Empires and Wellness', 'Inside the daily routines, mental health practices, and leadership strategies of the world''s most successful founders.', 'Sarah Jenkins', 'Sarah is the Senior Business Editor at Glamour. She covers the intersection of corporate leadership, culture, and personal development.', 'https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?ixlib=rb-4.0.3&auto=format&fit=crop&w=200&q=80', 'https://images.unsplash.com/photo-1507679799987-c73779587ccf?ixlib=rb-4.0.3&auto=format&fit=crop&w=1200&q=80', '', '2026-08-20', ARRAY['Leadership','Wellness','Business']::text[], false, false, 'You cannot pour from an empty cup. My best business decisions are made after a good night''s sleep and a morning run.', ARRAY['The archetype of the CEO has changed dramatically over the last decade. Gone are the days of the ruthless, 100-hour-workweek executive who sacrifices everything at the altar of profit. Today''s most successful founders are proving that personal wellness and corporate success are not mutually exclusive.','From morning meditation routines to strict digital detoxes on the weekend, the modern CEO is prioritizing mental health just as much as quarterly earnings. This shift isn''t just good for the leader; it creates a healthier, more sustainable company culture from the top down.','We sat down with five Fortune 500 CEOs to understand their daily habits, their biggest challenges, and how they maintain their humanity while steering massive global ships.']::text[]),
