-- =====================================================================
-- Authors — a dedicated place to manage bio/photo per person, separate
-- from any single story. `name` is the key (matches stories.author).
-- =====================================================================

create table if not exists authors (
  name text primary key,
  bio text default '',
  image text default '',
  created_at timestamptz default now()
);

alter table authors enable row level security;

drop policy if exists "Public read access" on authors;
create policy "Public read access" on authors
  for select to anon, authenticated using (true);

drop policy if exists "Admins can insert" on authors;
create policy "Admins can insert" on authors
  for insert to authenticated
  with check (exists (select 1 from admins where user_id = auth.uid()));

drop policy if exists "Admins can update" on authors;
create policy "Admins can update" on authors
  for update to authenticated
  using (exists (select 1 from admins where user_id = auth.uid()))
  with check (exists (select 1 from admins where user_id = auth.uid()));

drop policy if exists "Admins can delete" on authors;
create policy "Admins can delete" on authors
  for delete to authenticated
  using (exists (select 1 from admins where user_id = auth.uid()));

-- One-time migration: seed the authors table from whatever is currently
-- in your live stories table (the original seed data plus anything
-- you've already published), using each author's most recent story as
-- their starting bio/photo. Safe to re-run — existing rows are kept.
insert into authors (name, bio, image)
select distinct on (author) author, author_bio, author_image
from stories
where author is not null and author <> ''
order by author, story_date desc
on conflict (name) do nothing;

-- Magazine cover gallery: past and current covers, shown on the homepage.
create table if not exists covers (
  id text primary key,
  title text default '',
  image text not null,
  issue_date date default current_date,
  created_at timestamptz default now()
);

alter table covers enable row level security;

drop policy if exists "Public read access" on covers;
create policy "Public read access" on covers
  for select to anon, authenticated using (true);

drop policy if exists "Admins can insert" on covers;
create policy "Admins can insert" on covers
  for insert to authenticated
  with check (exists (select 1 from admins where user_id = auth.uid()));

drop policy if exists "Admins can update" on covers;
create policy "Admins can update" on covers
  for update to authenticated
  using (exists (select 1 from admins where user_id = auth.uid()))
  with check (exists (select 1 from admins where user_id = auth.uid()));

drop policy if exists "Admins can delete" on covers;
create policy "Admins can delete" on covers
  for delete to authenticated
  using (exists (select 1 from admins where user_id = auth.uid()));

